{
  "schemaVersion": 1,
  "date": "2026-10-11",
  "interview": [
    {
      "id": "interview-01",
      "articleIds": [
        "2026-10-11-top-1"
      ],
      "question": "大きなファイルをAIに読ませたとき、読み取りの完全性をどう確認しますか。",
      "answer": "ツールが返した量を実物と比べます。記事の三千行のファイルは、通常は七百三十二行で打ち切られ、allow_largeでは末尾まで返りました。truncatedByTokenCapと行数を確認します。ただし、一ターンで止めたため、理解の証明ではありません。必要な内容が回答に使われたかは別に確かめます。"
    },
    {
      "id": "interview-02",
      "articleIds": [
        "2026-10-11-top-2"
      ],
      "question": "分類モデルの確信度を、人の確認へ回す基準に使えますか。",
      "answer": "正解率と確信度を分けて確認します。記事のDecisions APIは、架空の書類二十八枚を全問正解し、confidenceも全部一でした。ただし、誤ったときに値が下がるかは未確認です。Clefの基準をそのまま移さず、別の紛らわしい書類で誤りと確認漏れを調べます。"
    },
    {
      "id": "interview-03",
      "articleIds": [
        "2026-10-11-top-3"
      ],
      "question": "WAFで怪しい送信元を止めるとき、誤検知をどう抑えますか。",
      "answer": "巻き添えになる利用者を先に調べます。JA4は、正規のブラウザや社内ツールでも同じ値になります。Bot Scoreなどと組み合わせ、まず記録で対象を見ます。ただし、一部の機能は契約が前提です。決め手がなければ保留し、止めなかった理由も残します。"
    },
    {
      "id": "interview-04",
      "articleIds": [
        "2026-10-11-top-4"
      ],
      "question": "DNS Firewallの新しい分析画面で、何を確認すればよいですか。",
      "answer": "設定、記録、表示を分けて確認します。記事はBLOCKルールをVPCに付け、CloudWatch Logsで拒否の記録を確認しました。分析タブではVpcFirewallQueryVolumeが見えました。ただし、Contributor Insightsの出力は未確認です。全機能が動いたとは扱いません。"
    },
    {
      "id": "interview-05",
      "articleIds": [
        "2026-10-11-top-5"
      ],
      "question": "新しいリポジトリだけAWSへのOIDC認証が失敗したら、どう調べますか。",
      "answer": "権限、aud、subを分けて確認します。記事の新しいsubには不変の組織IDとリポジトリIDが入り、古い信頼条件と一致しませんでした。実物に条件を合わせて認証を確かめます。ただし、IDのワイルドカードは同名の作り直しも通せます。固定するなら数値IDまで限定します。"
    }
  ],
  "review": [
    {
      "id": "review-01",
      "articleIds": [
        "2026-10-11-top-1"
      ],
      "question": "ファイルの全文取得と、内容の理解はどう分けて確認しますか。",
      "points": {
        "zh": "原文用返回行数、尾部和truncatedByTokenCap确认读取；max-turns=1在结果回到模型前停止，所以理解和答案依据须另行检验。",
        "ja": "行数、末尾とtruncatedByTokenCapで取得を確かめます。一ターンで結果を戻す前に止めたため、理解や回答への反映は別の検証です。"
      }
    },
    {
      "id": "review-02",
      "articleIds": [
        "2026-10-11-top-2"
      ],
      "question": "全件正解でconfidenceが全部一なら、確認の基準は決められますか。",
      "points": {
        "zh": "28张架空样本没有错误案例，不能证明答错时分数会降低。另备难例观察错误、分数和漏审，并分开比较Clef与flash的费用时间。",
        "ja": "誤りの事例がないので、失敗時に値が下がるか分かりません。別の難しい書類で誤りと確認漏れを測り、費用・時間もモデル別に比べます。"
      }
    },
    {
      "id": "review-03",
      "articleIds": [
        "2026-10-11-top-3",
        "2026-10-11-top-4",
        "2026-10-11-top-5"
      ],
      "question": "防御と認証の変更を、何の証拠で受け入れますか。",
      "points": {
        "zh": "WAF看正常用户和规则顺序；DNS分别查解析拒绝、BLOCK日志与指标，未见分析输出保持未确认；OIDC查真实claim与精确ID条件，另核业务权限。",
        "ja": "WAFは正常な通信とルールの順番、DNSは拒否・ログ・表示を確認します。未確認の分析は残します。OIDCは実物のclaimとIDを照合し、業務権限も別に調べます。"
      }
    }
  ]
}
